# Ablation: rebuild model with selected constraint families disabled to find infeasibility culprit
import json, numpy as np, os
from scipy import sparse
from scipy.optimize import milp, Bounds, LinearConstraint

d = json.load(open('network.json'))
T = d['time_periods']
demand = np.array(d['demand'], float); reserve_req = np.array(d['reserves'], float)
th_names = list(d['thermal_generators'].keys()); rn_names = list(d['renewable_generators'].keys())
G, R = len(th_names), len(rn_names)
TH = [d['thermal_generators'][n] for n in th_names]; RN = [d['renewable_generators'][n] for n in rn_names]
pmin = np.array([g['power_output_minimum'] for g in TH]); pmax = np.array([g['power_output_maximum'] for g in TH])
cap = pmax - pmin; ru = np.array([g['ramp_up_limit'] for g in TH]); rd = np.array([g['ramp_down_limit'] for g in TH])
mu = np.array([g['time_up_minimum'] for g in TH], int); md = np.array([g['time_down_minimum'] for g in TH], int)
p0 = np.array([g['power_output_t0'] for g in TH]); on0 = np.array([g['unit_on_t0'] for g in TH], int)
up0 = np.array([g['time_up_t0'] for g in TH], int); dn0 = np.array([g['time_down_t0'] for g in TH], int)
mustrun = np.array([g['must_run'] for g in TH], int)
init_am = np.where(on0==1, p0-pmin, 0.0)
curves = [[(p['mw'],p['cost']) for p in g['piecewise_production']] for g in TH]
tiers = [sorted(g['startup'], key=lambda z: z['lag']) for g in TH]
nseg = [len(c)-1 for c in curves]
seg_width = [[c[i+1][0]-c[i][0] for i in range(len(c)-1)] for c in curves]
seg_slope = [[(c[i+1][1]-c[i][1])/(c[i+1][0]-c[i][0]) for i in range(len(c)-1)] for c in curves]
cost0 = np.array([c[0][1] for c in curves])
tier_lag = [[s['lag'] for s in t] for t in tiers]; tier_cost = [[s['cost'] for s in t] for t in tiers]

def window_off_info(g, t, L):
    wh = list(range(max(0,t-L), t)); pre = list(range(t-L, max(0,t-L)))
    if on0[g]==1:
        return wh, 0, len(pre)>0
    D0 = dn0[g]
    return wh, sum(1 for s in pre if -s<=D0), any(-s>D0 for s in pre)

def build(flags):
    lb_list, ub_list, int_list = [], [], []; nvars=0
    def alloc(shape, lb, ub, integ):
        nonlocal nvars
        size = int(np.prod(shape)); idx = np.arange(nvars, nvars+size).reshape(shape)
        lb_list.extend([lb]*size); ub_list.extend([ub]*size); int_list.extend([integ]*size); nvars += size
        return idx
    u = alloc((G,T),0,1,True); y = alloc((G,T),0,1,True); w = alloc((G,T),0,1,True)
    seg = [alloc((T,nseg[g]),0,float('inf'),False) for g in range(G)]
    r = alloc((G,T),0,float('inf'),False)
    su, z = {}, {}
    for g in range(G):
        if len(tiers[g])>1:
            su[g] = alloc((T,len(tiers[g])),0,1,True); z[g] = alloc((T,len(tiers[g])),0,1,True)
    re = alloc((R,T),0,float('inf'),False)
    for g in range(G):
        for k in range(nseg[g]):
            for t in range(T):
                j = seg[g][t,k]; lb_list[j]=0.0; ub_list[j]=seg_width[g][k]
        if mustrun[g]:
            for t in range(T): lb_list[u[g,t]]=1.0
        for t in range(T): ub_list[r[g,t]]=cap[g]
    for i in range(R):
        for t in range(T):
            lb_list[re[i,t]] = RN[i]['power_output_minimum'][t]; ub_list[re[i,t]] = RN[i]['power_output_maximum'][t]
    for g in range(G):
        if len(tiers[g])<=1: continue
        for t in range(T):
            for k in range(len(tiers[g])):
                L = tier_lag[g][k]; wh, pre_off, any_pre_on = window_off_info(g,t,L)
                j = z[g][t,k]
                if any_pre_on: ub_list[j]=0.0
                elif len(wh)==0 and pre_off==L: lb_list[j]=1.0
    lb = np.array(lb_list); ub = np.array(ub_list); integ = np.array(int_list)
    rows, cols, vals, rlo, rhi = [],[],[],[],[]; row=[0]
    def add_row(terms, lo, hi):
        for j,a in terms:
            if a != 0.0: rows.append(row[0]); cols.append(j); vals.append(float(a))
        rlo.append(lo); rhi.append(hi); row[0]+=1
    for g in range(G):
        for t in range(T):
            segs = [(seg[g][t,k],1.0) for k in range(nseg[g])]
            add_row(segs + [(u[g,t],-cap[g])], -np.inf, 0.0)
            if flags.get('startcap',1):
                add_row(segs + [(r[g,t],1.0),(u[g,t],-cap[g]),(y[g,t],cap[g])], -np.inf, 0.0)
            if flags.get('stopcap',1) and t+1<T:
                add_row(segs + [(r[g,t],1.0),(u[g,t],-cap[g]),(w[g,t+1],cap[g])], -np.inf, 0.0)
            if t==0:
