            else:
                add_row([(u[g,t],1.0),(u[g,t-1],-1.0),(y[g,t],-1.0),(w[g,t],1.0)],0.0,0.0)
            if flags.get('minupdown',1):
                s0 = max(0,t-mu[g]+1)
                add_row([(y[g,s],1.0) for s in range(s0,t+1)]+[(u[g,t],-1.0)],-np.inf,0.0)
                s0 = max(0,t-md[g]+1)
                add_row([(w[g,s],1.0) for s in range(s0,t+1)]+[(u[g,t],1.0)],-np.inf,1.0)
            if flags.get('tiers',1) and len(tiers[g])>1:
                add_row([(su[g][t,k],1.0) for k in range(len(tiers[g]))]+[(y[g,t],-1.0)],0.0,0.0)
                for k in range(len(tiers[g])):
                    add_row([(su[g][t,k],1.0),(z[g][t,k],-1.0)],-np.inf,0.0)
                    zn = z[g][t,k+1] if k+1<len(tiers[g]) else None
                    trms = [(su[g][t,k],1.0),(y[g,t],-1.0),(z[g][t,k],-1.0)]
                    if zn is not None: trms.append((zn,1.0))
                    add_row(trms,-np.inf,-1.0)
                    L = tier_lag[g][k]; wh, pre_off, any_pre_on = window_off_info(g,t,L)
                    if not any_pre_on:
                        for s in wh: add_row([(z[g][t,k],1.0),(u[g,s],1.0)],-np.inf,1.0)
                        if len(wh)+pre_off-L+1 > 0:
                            add_row([(z[g][t,k],1.0)]+[(u[g,s],1.0) for s in wh], len(wh)+pre_off-L+1, np.inf)
    for t in range(T):
        terms=[]
        for g in range(G):
            terms.append((u[g,t],pmin[g])); terms.extend([(seg[g][t,k],1.0) for k in range(nseg[g])])
        for i in range(R): terms.append((re[i,t],1.0))
        add_row(terms, demand[t], demand[t])
        if flags.get('reserve',1):
            add_row([(r[g,t],1.0) for g in range(G)], reserve_req[t], np.inf)
    A = sparse.csc_matrix((vals,(rows,cols)), shape=(row[0], nvars))
    return milp(c=np.zeros(nvars), integrality=integ, bounds=Bounds(lb,ub),
                constraints=LinearConstraint(A, np.array(rlo), np.array(rhi)),
                options={"time_limit":60.0,"mip_rel_gap":0.01})

base = {}
res = build(base)
print("FULL MODEL:", res.status, res.message[:60])
fams = ['startcap','stopcap','ramp','minupdown','tiers','reserve']
for f in fams:
    flags = dict(base); flags[f]=0
    res = build(flags)
